#include <algorithm>
#include <string>
#include <string_view>
#include <vector>

struct Record { int id; std::string name; };
struct Entry { std::string_view key; int id; };

std::vector<Entry> Snapshot(const std::vector<Record>& input) {
  std::vector<Entry> result;
  for (const auto& row : input) result.push_back({row.name, row.id});
  std::ranges::stable_sort(result, {}, &Entry::key);
  return result;
}
